effect.shader:
vec2 wrapUV(vec2 p) {
if (edgeMode == 0) {
return clamp(p, 0.0, 1.0);
} else {
return fract(p);
}
}
vec2 pickChannels(vec4 c) {
if (channelPair == 0) {
return c.rg;
} else if (channelPair == 1) {
return c.rb;
} else {
return c.gb;
}
}
void main() {
vec2 uv = acScreenNorm;
vec4 jc = useLayerBelow ? texture2DCv(mapComp.texture, uv)
: texture2DCv(mapImg.texture, uv);
uv -= vec2(offsetX, offsetY);
vec2 disp = pickChannels(jc) * mapAmount;
vec2 dispUV = uv + disp;
vec2 sampleUV = wrapUV(dispUV);
vec4 displacedCol = texture2DCv(inputImg.texture, sampleUV);
vec2 overNeg = max(-dispUV, vec2(0.0));
vec2 overPos = max(dispUV - vec2(1.0), vec2(0.0));
float o = max(max(overNeg.x, overNeg.y), max(overPos.x, overPos.y));
vec2 clampUV = clamp(dispUV, 0.0, 1.0);
vec4 clampCol = texture2DCv(inputImg.texture, clampUV);
float feather = edgeFeather;
float m = feather > 0.0 ? smoothstep(0.0, feather, o) : 0.0;
vec4 col = mix(displacedCol, clampCol, m);
gl_FragColor = col;
}
